    public function __construct(private $db) {}

    public function candidatePayments(?int $clientId=null):array
    {
        $allocations=$this->db->prefixTable('payment_allocations');
        $payments=$this->db->prefixTable('payment_complement_payments');
        $complements=$this->db->prefixTable('payment_complements');
        $q=$this->db->table('invoice_payments p')->select("p.id,p.client_id,p.payment_date,p.amount,c.company_name client_name,pm.title payment_method,fa.name account_name,COALESCE((SELECT SUM(a.amount_applied) FROM {$allocations} a WHERE a.invoice_payment_id=p.id AND a.status='active' AND a.deleted=0),0) applied_amount",false)
            ->join('clients c','c.id=p.client_id')->join('payment_methods pm','pm.id=p.payment_method_id','left')->join('financial_accounts fa','fa.id=p.destination_financial_account_id','left')
            ->where(['p.deleted'=>0,'p.status'=>'active'])->where('p.amount >',0)
            ->where("NOT EXISTS (SELECT 1 FROM {$payments} pp JOIN {$complements} pc ON pc.id=pp.payment_complement_id LEFT JOIN ".$this->db->prefixTable('fiscal_documents')." pfd ON pfd.id=pc.fiscal_document_id WHERE pp.source_invoice_payment_id=p.id AND pp.deleted=0 AND pc.deleted=0 AND (pc.status IN ('draft','complete_draft') OR (pc.status='stamped' AND COALESCE(pfd.status,'')<>'cancelled')))",null,false);
        if($clientId)$q->where('p.client_id',$clientId);
        $out=[];foreach($q->orderBy('p.payment_date','DESC')->orderBy('p.id','DESC')->get()->getResult() as$p){$p->amount=$this->decimal($p->amount);$p->applied_amount=$this->decimal($p->applied_amount);$available=FiscalDecimal::subtract($p->amount,$p->applied_amount);$p->available_amount=FiscalDecimal::micros($available)>0?$available:'0.000000';$out[]=$p;}return$out;
    }

    public function eligibleForPayment(int$paymentId,?int$complementId=null):array
    {
        $allocationService=new PaymentAllocationService($this->db);$payment=$allocationService->payment($paymentId);if(!$payment||$payment->status!=='active'||(int)$payment->deleted)return[];
        $included='0.000000';if($complementId){$snapshot=$this->db->table('payment_complement_payments')->where(['payment_complement_id'=>$complementId,'deleted'=>0])->get(1)->getRow();if($snapshot)$included=$this->includedAmount((int)$snapshot->id);}
        $paymentAvailable=FiscalDecimal::subtract($this->decimal($payment->amount),$included);if(FiscalDecimal::micros($paymentAvailable)<0)$paymentAvailable='0.000000';
        $rows=$this->db->table('fiscal_documents d')->select('d.id fiscal_document_id,COALESCE(fds.sale_id,d.invoice_id) invoice_id,d.total document_total,d.issue_date document_date,d.currency_code,d.series,d.folio,i.display_id,i.invoice_total sale_total,pa.id allocation_id,COALESCE(pa.amount_applied,0) allocation_amount,s.uuid',false)
            ->join('fiscal_document_sales fds',"fds.fiscal_document_id=d.id AND fds.allocation_status<>'cancelled'",'left')->join($this->db->prefixTable('invoices').' i','i.id=COALESCE(fds.sale_id,d.invoice_id)','inner',false)->join('fiscal_document_stamps s','s.fiscal_document_id=d.id')->join('payment_allocations pa',"pa.invoice_payment_id={$paymentId} AND pa.invoice_id=i.id AND pa.status='active' AND pa.deleted=0",'left')
            ->where(['i.client_id'=>(int)$payment->client_id,'i.deleted'=>0,'i.type'=>'invoice','d.deleted'=>0,'d.status'=>'stamped','d.payment_method_code'=>'PPD'])->groupStart()->where('d.document_type','income')->orWhere('d.document_type','ingreso')->orWhere('d.document_type','I')->groupEnd()->whereNotIn('i.status',['cancelled','credited'])->where('i.commercial_status !=','cancelled')->where('d.cancelled_at',null)->where('s.uuid !=','')->groupBy('d.id,COALESCE(fds.sale_id,d.invoice_id),i.display_id,i.invoice_total,pa.id,pa.amount_applied,s.uuid')->orderBy('d.issue_date')->orderBy('d.id')->get()->getResult();
        $balances=new \App\Services\Fiscal\FiscalInvoiceOutstandingBalanceService($this->db);$out=[];foreach($rows as$r){if($complementId&&$this->documentSelectedInComplement((int)$r->fiscal_document_id,$complementId))continue;$balance=$balances->breakdown((int)$r->fiscal_document_id,$complementId);if(FiscalDecimal::micros($balance['available'])<=0)continue;$maximum=$this->minimum([$balance['available'],$paymentAvailable]);if(FiscalDecimal::micros($maximum)<=0)continue;$r->allocation_id=(int)($r->allocation_id??0);$r->allocation_amount=$this->decimal($r->allocation_amount);$r->payment_available=$paymentAvailable;$r->fiscal_total=$balance['total'];$r->prior_fiscal_paid=$balance['stamped_payments'];$r->active_credit_notes=$balance['active_credit_notes'];$r->fiscal_reserved=$balance['reserved'];$r->fiscal_outstanding=$balance['outstanding'];$r->fiscal_available=$maximum;$r->installment_number=$balance['installment_number'];$r->previous_balance=$balance['outstanding'];$r->remaining_balance=FiscalDecimal::subtract($balance['outstanding'],$maximum);$out[]=$r;}return$out;
    }

    public function createFromPayment(int$clientId,int$paymentId,?int$actor):int
    {
        $this->db->transBegin();try{$p=$this->db->query('SELECT * FROM '.$this->db->prefixTable('invoice_payments').' WHERE id=? FOR UPDATE',[$paymentId])->getRow();if(!$p||(int)$p->deleted||$p->status!=='active'||FiscalDecimal::micros((string)$p->amount)<=0)throw new RuntimeException('El pago administrativo no está activo.');if((int)$p->client_id!==$clientId)throw new RuntimeException('El pago no pertenece al cliente seleccionado.');$existing=$this->db->table('payment_complement_payments pp')->select('pc.id,pc.status,fd.status fiscal_status')->join('payment_complements pc','pc.id=pp.payment_complement_id')->join('fiscal_documents fd','fd.id=pc.fiscal_document_id','left')->where(['pp.source_invoice_payment_id'=>$paymentId,'pp.deleted'=>0,'pc.deleted'=>0])->groupStart()->whereIn('pc.status',['draft','complete_draft'])->orGroupStart()->where('pc.status','stamped')->where('fd.status !=','cancelled')->groupEnd()->groupEnd()->get(1)->getRow();if($existing)throw new RuntimeException($existing->status==='stamped'?'El pago ya tiene un Complemento timbrado vigente.':'El pago ya tiene un borrador activo. Continúe el borrador existente.');$mapping=$this->db->table('fiscal_payment_method_mappings')->where(['payment_method_id'=>(int)$p->payment_method_id,'is_active'=>1])->get(1)->getRow();$account=$this->db->table('financial_accounts')->where('id',(int)$p->destination_financial_account_id)->get(1)->getRow();$now=(new \App\Services\Fiscal\FiscalIssueDateService())->nowForSnapshot();$this->db->table('payment_complements')->insert(['client_id'=>$clientId,'issue_date'=>$now,'status'=>'draft','created_by'=>$actor,'created_at'=>get_current_utc_time(),'updated_at'=>get_current_utc_time(),'deleted'=>0]);$cid=(int)$this->db->insertID();$this->db->table('payment_complement_payments')->insert(['payment_complement_id'=>$cid,'source_invoice_payment_id'=>$paymentId,'payment_date'=>$p->payment_date,'payment_form_code'=>$mapping->sat_payment_form_code??null,'currency_code'=>'MXN','exchange_rate'=>'1.000000','amount'=>'0.000000','operation_number'=>$p->note?:null,'beneficiary_bank_rfc'=>$account->bank_rfc??null,'beneficiary_account'=>($account->clabe??null)?:($account->account_number??null),'created_at'=>get_current_utc_time(),'updated_at'=>get_current_utc_time(),'deleted'=>0]);if(!$this->db->transStatus())throw new RuntimeException('No fue posible crear el borrador.');$this->db->transCommit();return$cid;}catch(Throwable$e){$this->db->transRollback();throw$e;}
    }

    public function emptyEligibilityReason(int$paymentId):string
    {
        $payment=$this->db->table('invoice_payments')->where(['id'=>$paymentId,'deleted'=>0,'status'=>'active'])->get(1)->getRow();
        if(!$payment)return'El pago administrativo no está activo.';
        $base=function()use($payment){return$this->db->table('fiscal_documents d')->join('fiscal_document_sales fds',"fds.fiscal_document_id=d.id AND fds.allocation_status<>'cancelled'",'left')->join($this->db->prefixTable('invoices').' i','i.id=COALESCE(fds.sale_id,d.invoice_id)','inner',false)->where(['i.client_id'=>(int)$payment->client_id,'i.deleted'=>0,'d.deleted'=>0])->groupStart()->where('d.document_type','income')->orWhere('d.document_type','ingreso')->orWhere('d.document_type','I')->groupEnd();};
        if(!$base()->countAllResults())return'El cliente no tiene facturas fiscales de ingreso relacionadas.';
        if(!$base()->where('d.status','stamped')->join('fiscal_document_stamps s','s.fiscal_document_id=d.id')->where('s.uuid !=','')->countAllResults())return'El cliente no tiene facturas timbradas vigentes.';
        if(!$base()->where(['d.status'=>'stamped','d.payment_method_code'=>'PPD'])->where('d.cancelled_at',null)->countAllResults())return'Las facturas timbradas del cliente están canceladas o no usan método PPD.';
        return'Las facturas PPD del cliente no tienen saldo fiscal disponible o ya están reservadas en otro complemento.';
    }

    public function addDocumentDiagnostics(int$complementId,int$fiscalDocumentId,$requestedAmount):array
    {
        $row=$this->db->table('payment_complements c')->select('c.status complement_status,c.client_id,p.source_invoice_payment_id,p.amount included_amount,ip.amount payment_amount,d.status document_status,d.document_type,d.payment_method_code,d.total document_total,COALESCE(fds.sale_id,d.invoice_id) sale_id,r.id receiver_id,r.rfc receiver_rfc',false)
            ->join('payment_complement_payments p','p.payment_complement_id=c.id AND p.deleted=0','left')->join('invoice_payments ip','ip.id=p.source_invoice_payment_id','left')
            ->join('fiscal_documents d','d.id='.$fiscalDocumentId,'left')->join('fiscal_document_sales fds','fds.fiscal_document_id=d.id','left')
            ->join('fiscal_document_receivers r','r.fiscal_document_id=d.id','left')->where('c.id',$complementId)->get(1)->getRow();
        $out=['payment_complement_id'=>$complementId,'fiscal_document_id'=>$fiscalDocumentId,'requested_amount'=>(string)$requestedAmount];if(!$row)return$out+['validation_code'=>'COMPLEMENT_NOT_FOUND'];
        foreach((array)$row as$key=>$value)$out[$key]=$value;
        $included=$this->decimal($row->included_amount??'0');$paymentAmount=$this->decimal($row->payment_amount??'0');$out['payment_available']=FiscalDecimal::subtract($paymentAmount,$included);
        try{$balance=(new \App\Services\Fiscal\FiscalInvoiceOutstandingBalanceService($this->db))->breakdown($fiscalDocumentId,$complementId);$out+=['fiscal_outstanding'=>$balance['outstanding'],'fiscal_reserved'=>$balance['reserved'],'fiscal_available'=>$balance['available']];}catch(Throwable$e){$out['balance_error']=$e->getMessage();}
        return$out;
    }

    public function addDocument(int$complementId,int$fiscalDocumentId,$requestedAmount,?int$actor):int
    {
        $this->db->transBegin();
        try {
            $context=$this->lockedContext($complementId);
            $this->db->query('SELECT id FROM '.$this->db->prefixTable('invoice_payments').' WHERE id=? FOR UPDATE',[$context->source_invoice_payment_id]);
            $this->db->query('SELECT id FROM '.$this->db->prefixTable('fiscal_documents').' WHERE id=? FOR UPDATE',[$fiscalDocumentId]);
            $candidate=null;
            foreach($this->eligibleForPayment((int)$context->source_invoice_payment_id,$complementId)as$row)if((int)$row->fiscal_document_id===$fiscalDocumentId){$candidate=$row;break;}
            if(!$candidate)throw new RuntimeException('La factura ya no está disponible para este pago.');
            $amount=$this->decimal($requestedAmount);if(FiscalDecimal::micros($amount)<=0)throw new RuntimeException('El importe debe ser mayor que cero.');
            $included=$this->includedAmount((int)$context->payment_snapshot_id);$payment=$this->db->table('invoice_payments')->where('id',$context->source_invoice_payment_id)->get(1)->getRow();
            $draftAvailable=FiscalDecimal::subtract((string)$payment->amount,$included);$maximum=$this->minimum([$candidate->fiscal_available,$draftAvailable]);
            if(FiscalDecimal::micros($amount)>FiscalDecimal::micros($maximum))throw new RuntimeException('El importe excede el máximo disponible para esta factura o pago.');
            $allocationId=(int)$candidate->allocation_id?:null;$origin=$allocationId?'preexisting':'none';$previous=$this->decimal($candidate->allocation_amount);
            $remaining=FiscalDecimal::subtract($candidate->previous_balance,$amount);$now=get_current_utc_time();
            $snapshot=['payment_id'=>(int)$context->source_invoice_payment_id,'allocation_id'=>$allocationId,'allocation_origin'=>$origin,'invoice_id'=>(int)$candidate->invoice_id,'fiscal_document_id'=>(int)$candidate->fiscal_document_id,'uuid'=>$candidate->uuid,'series'=>$candidate->series,'folio'=>$candidate->folio,'payment_method_code'=>'PPD'];
            $this->db->table('payment_complement_documents')->insert(['payment_complement_payment_id'=>(int)$context->payment_snapshot_id,'payment_allocation_id'=>$allocationId,'allocation_origin'=>$origin,'allocation_amount_before'=>$previous,'allocation_amount_after'=>$previous,'invoice_id'=>(int)$candidate->invoice_id,'fiscal_document_id'=>(int)$candidate->fiscal_document_id,'document_uuid'=>$candidate->uuid,'currency_dr'=>$candidate->currency_code?:'MXN','equivalence_dr'=>'1.000000','installment_number'=>(int)$candidate->installment_number,'previous_balance'=>$candidate->previous_balance,'amount_paid'=>$amount,'remaining_balance'=>$remaining,'tax_object_code'=>'02','snapshot_json'=>json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'created_at'=>$now,'updated_at'=>$now,'deleted'=>0]);
            $id=(int)$this->db->insertID();$this->syncTotals($complementId,(int)$context->payment_snapshot_id);if(!$this->db->transStatus())throw new RuntimeException('No fue posible agregar la factura.');
            $this->db->transCommit();return$id;
        } catch(Throwable$e) {$this->db->transRollback();throw$e;}
    }

    public function removeDocument(int$complementId,int$documentId,?int$actor):void
    {
        $this->db->transBegin();try{$context=$this->lockedContext($complementId);$row=$this->db->query('SELECT * FROM '.$this->db->prefixTable('payment_complement_documents').' WHERE id=? FOR UPDATE',[$documentId])->getRow();if(!$row||(int)$row->deleted||(int)$row->payment_complement_payment_id!==(int)$context->payment_snapshot_id)throw new RuntimeException('La factura no pertenece al borrador.');$this->restoreAutomaticAllocation($row,$actor,'Factura retirada del borrador de Complemento #'.$complementId);$this->db->table('payment_complement_documents')->where('id',$documentId)->update(['deleted'=>1,'updated_at'=>get_current_utc_time()]);$this->syncTotals($complementId,(int)$context->payment_snapshot_id);if(!$this->db->transStatus())throw new RuntimeException('No fue posible quitar la factura.');$this->db->transCommit();}catch(Throwable$e){$this->db->transRollback();throw$e;}
    }

    public function context(int$id):array
    {
        $c=$this->db->table('payment_complements c')->select('c.*,cl.company_name,cl.vat_number')->join('clients cl','cl.id=c.client_id')->where(['c.id'=>$id,'c.deleted'=>0])->get(1)->getRow();if(!$c)throw new RuntimeException('Borrador no encontrado.');$p=$this->db->table('payment_complement_payments p')->select('p.*,ip.amount received_amount,ip.payment_method_id,ip.note payment_reference,pm.title payment_method,fa.name account_name,fa.bank_name account_bank_name,fa.bank_rfc account_bank_rfc,fa.account_number account_number,fa.clabe account_clabe,fm.sat_payment_form_code mapped_payment_form,sf.name sat_payment_form_name')->join('invoice_payments ip','ip.id=p.source_invoice_payment_id')->join('payment_methods pm','pm.id=ip.payment_method_id','left')->join('financial_accounts fa','fa.id=ip.destination_financial_account_id','left')->join('fiscal_payment_method_mappings fm','fm.payment_method_id=ip.payment_method_id AND fm.is_active=1','left')->join('sat_payment_forms sf','sf.code=fm.sat_payment_form_code AND sf.is_active=1','left')->where(['p.payment_complement_id'=>$id,'p.deleted'=>0])->get(1)->getRow();if(!$p)throw new RuntimeException('El borrador no tiene pago origen.');$p->effective_payment_form=$p->payment_form_code?:$p->mapped_payment_form;$resolver=new FiscalDocumentHistoricalTaxResolver($this->db);$documents=$this->db->table('payment_complement_documents d')->select('d.*,fd.series,fd.folio,fd.issue_date document_date,fd.total document_total')->join('fiscal_documents fd','fd.id=d.fiscal_document_id')->where(['d.payment_complement_payment_id'=>$p->id,'d.deleted'=>0])->orderBy('d.id')->get()->getResult();foreach($documents as$d){try{$h=$resolver->resolve((int)$d->fiscal_document_id);$d->tax_object_code_derived=$h['tax_object_code'];$d->tax_details=$resolver->prorate($h,(string)$d->amount_paid,(string)$d->previous_balance);}catch(Throwable$e){$d->tax_object_code_derived=null;$d->tax_details=[];$d->tax_error=$e->getMessage();}}$allocationService=new PaymentAllocationService($this->db);$administrative=$allocationService->paymentApplied((int)$p->source_invoice_payment_id);$administrativeAvailable=$allocationService->paymentAvailable((int)$p->source_invoice_payment_id);$included=$this->decimal($p->amount);$candidates=$this->eligibleForPayment((int)$p->source_invoice_payment_id,$id);$sum='0.000000';foreach($candidates as$row)$sum=FiscalDecimal::add($sum,$row->fiscal_available);$draftCapacity=FiscalDecimal::subtract((string)$p->received_amount,$included);$remaining=$this->minimum([$sum,$draftCapacity]);$normalizer=new \App\Services\Fiscal\FiscalIssueDateNormalizer();return['complement'=>$c,'payment'=>$p,'documents'=>$documents,'candidates'=>$candidates,'issue_date_input'=>$normalizer->formatForInput((string)$c->issue_date),'issue_date_constraints'=>(new \App\Services\Fiscal\FiscalIssueDatePolicy())->constraints(),'sat_payment_forms'=>$this->db->table('sat_payment_forms')->where('is_active',1)->orderBy('code')->get()->getResult(),'summary'=>['received'=>$this->decimal($p->received_amount),'administrative_applied'=>$administrative,'administrative_available'=>$administrativeAvailable,'fiscal_eligible'=>FiscalDecimal::add($included,$remaining),'included'=>$included,'remaining'=>$remaining]];
    }

    public function discard(int$id,?int$actor,string$reason):void
    {
        $reason=trim($reason);if($reason==='')throw new RuntimeException('El motivo es obligatorio.');$this->db->transBegin();try{$row=$this->db->query('SELECT * FROM '.$this->db->prefixTable('payment_complements').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$row||(int)$row->deleted)throw new RuntimeException('El borrador no existe.');if($row->status==='stamped')throw new RuntimeException('Un complemento timbrado es inmutable.');if($row->status==='cancelled')throw new RuntimeException('El borrador ya fue descartado.');$docs=$this->db->table('payment_complement_documents d')->join('payment_complement_payments p','p.id=d.payment_complement_payment_id')->where(['p.payment_complement_id'=>$id,'d.deleted'=>0,'p.deleted'=>0])->get()->getResult();foreach($docs as$doc)$this->restoreAutomaticAllocation($doc,$actor,'Borrador de Complemento #'.$id.' descartado');$now=get_current_utc_time();$this->db->table('payment_complements')->where('id',$id)->update(['status'=>'cancelled','cancelled_at'=>$now,'cancelled_by'=>$actor,'cancellation_reason'=>$reason,'updated_at'=>$now]);if(!$this->db->transStatus())throw new RuntimeException('No fue posible descartar el borrador.');$this->db->transCommit();}catch(Throwable$e){$this->db->transRollback();throw$e;}
    }

    private function restoreAutomaticAllocation(object$row,?int$actor,string$reason):void{if(!in_array((string)$row->allocation_origin,['complement_created','complement_increased'],true))return;(new PaymentAllocationService($this->db))->restoreWithinTransaction((int)$row->payment_allocation_id,(string)$row->allocation_amount_after,(string)$row->allocation_amount_before,$actor,$reason);}
    private function lockedContext(int$id):object{$c=$this->db->query('SELECT * FROM '.$this->db->prefixTable('payment_complements').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$c||!in_array($c->status,['draft','complete_draft'],true)||(int)$c->deleted)throw new RuntimeException('El borrador no es editable.');$p=$this->db->query('SELECT * FROM '.$this->db->prefixTable('payment_complement_payments').' WHERE payment_complement_id=? AND deleted=0 FOR UPDATE',[$id])->getRow();if(!$p)throw new RuntimeException('Pago origen no encontrado.');$c->payment_snapshot_id=(int)$p->id;$c->source_invoice_payment_id=(int)$p->source_invoice_payment_id;return$c;}
    private function syncTotals(int$cid,int$pid):void{$total=$this->includedAmount($pid);$now=get_current_utc_time();$this->db->table('payment_complement_payments')->where('id',$pid)->update(['amount'=>$total,'updated_at'=>$now]);$this->db->table('payment_complements')->where('id',$cid)->update(['status'=>FiscalDecimal::micros($total)>0?'complete_draft':'draft','updated_at'=>$now]);$this->db->table('payment_complement_fiscal_snapshots')->where('payment_complement_id',$cid)->delete();}
    private function includedAmount(int$pid):string{$r=$this->db->table('payment_complement_documents')->selectSum('amount_paid','total')->where(['payment_complement_payment_id'=>$pid,'deleted'=>0])->get()->getRow();return$this->decimal($r->total??'0');}
    private function documentSelectedInComplement(int$id,int$complementId):bool{return$this->db->table('payment_complement_documents d')->join('payment_complement_payments p','p.id=d.payment_complement_payment_id')->where(['d.fiscal_document_id'=>$id,'d.deleted'=>0,'p.deleted'=>0,'p.payment_complement_id'=>$complementId])->countAllResults()>0;}
    private function allocationConsumed(int$id):string{$r=$this->db->table('payment_complement_documents d')->selectSum('d.amount_paid','total')->join('payment_complement_payments p','p.id=d.payment_complement_payment_id')->join('payment_complements c','c.id=p.payment_complement_id')->join('fiscal_documents fd','fd.id=c.fiscal_document_id')->where(['d.payment_allocation_id'=>$id,'d.deleted'=>0,'p.deleted'=>0,'c.deleted'=>0,'c.status'=>'stamped'])->where('fd.status !=','cancelled')->get()->getRow();return$this->decimal($r->total??'0');}
    private function stampedAmount(int$id):string{$r=$this->db->table('payment_complement_documents d')->selectSum('d.amount_paid','total')->join('payment_complement_payments p','p.id=d.payment_complement_payment_id')->join('payment_complements c','c.id=p.payment_complement_id')->join('fiscal_documents fd','fd.id=c.fiscal_document_id')->where(['d.fiscal_document_id'=>$id,'d.deleted'=>0,'p.deleted'=>0,'c.deleted'=>0,'c.status'=>'stamped'])->where('fd.status !=','cancelled')->get()->getRow();return$this->decimal($r->total??'0');}
    private function stampedInstallments(int$id):int{return$this->db->table('payment_complement_documents d')->join('payment_complement_payments p','p.id=d.payment_complement_payment_id')->join('payment_complements c','c.id=p.payment_complement_id')->join('fiscal_documents fd','fd.id=c.fiscal_document_id')->where(['d.fiscal_document_id'=>$id,'d.deleted'=>0,'p.deleted'=>0,'c.deleted'=>0,'c.status'=>'stamped'])->where('fd.status !=','cancelled')->countAllResults();}
    private function minimum(array$values):string{$min=null;foreach($values as$v){$v=$this->decimal($v);if($min===null||FiscalDecimal::micros($v)<FiscalDecimal::micros($min))$min=$v;}return$min??'0.000000';}
    private function decimal($v):string{return FiscalDecimal::format(FiscalDecimal::micros((string)$v));}
}
